Subroutine Suspendable Consultar(nombre As String, stock As Integer) As Result<Integer, String>
  If stock = 0 Then
    Return Failure(nombre + " no tiene stock");
  EndIf
  Return Success(stock);
EndSubroutine

Algorithm Pedido
  Define norte As Integer;
  Define sur As Integer;
  Define oeste As Integer;
  Read norte;
  Read sur;
  Read oeste;
  Tasks fallo
    Spawn Consultar("Norte", norte);
    Spawn Consultar("Sur", sur);
    Spawn Consultar("Oeste", oeste);
  EndTasks
  Switch fallo Do
    Some(problema): Write "Pedido suspendido: ", problema.first;
    None: Write "Pedido confirmado: ", norte + sur + oeste;
  EndSwitch
EndAlgorithm
